code_sketch:
sealed interface Payment permits Payment.Card, Payment.Transfer {
    record Card(String number) implements Payment {}
    record Transfer(String iban) implements Payment {}
}

String describe(Payment p) {
    return switch (p) {              // exhaustive: no default needed
        case Payment.Card c     -> c.number();
        case Payment.Transfer t -> t.iban();
    };
}

