}

String describe(Payment p) {
    return switch (p) {              // exhaustive: no default needed
        case Payment.Card c     -> c.number();
        case Payment.Transfer t -> t.iban();
    };
}

public abstract class Payment {
    private Payment() {}                       // only these cases can extend
    public static final class Card extends Payment {
        public final String number;
        public Card(String number) { this.number = number; }
    }
    public static final class Transfer extends Payment {
        public final String iban;
        public Transfer(String iban) { this.iban = iban; }
    }
}
